import{_ as t,c as n,j as e,a as r,o}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百二十三章 十种正邪行为","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/123第一百二十三章 十种正邪行为.md","filePath":"meditation/巴利文大藏经/123第一百二十三章 十种正邪行为.md"}'),_={name:"meditation/巴利文大藏经/123第一百二十三章 十种正邪行为.md"};function l(s,a,i,d,p,c){return o(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百二十三章-十种正邪行为",tabindex:"-1"},[r("第一百二十三章 十种正邪行为 "),e("a",{class:"header-anchor",href:"#第一百二十三章-十种正邪行为","aria-label":'Permalink to "第一百二十三章 十种正邪行为"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部14相应29经/十支经(界相应/因缘篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，世间的众生如同界（界解释，见第一百零三章）一样，相同特性的事物会聚集、合流到一起，也就是邪见的众生与邪见的众生聚集、合流到一起；邪意愿的众生与邪意愿的众生聚集、合流到一起；邪语的众生与邪语的众生聚集、合流到一起；由于恶行将会导致恶报的众生与由于恶行将会导致恶报的众生聚集、合流到一起；非法、不正当谋生的众生与非法、不正当谋生的众生聚集、合流到一起；向错误方向奋斗努力的众生与向错误方向奋斗努力的众生聚集、合流到一起；邪念的众生与邪念的众生聚集、合流到一起；用错误的修行方法想让内心清净无染的众生与用错误的修行方法想让内心清净无染的众生聚集、合流到一起；错误理解善行恶行、颠倒善恶的众生与错误理解善行恶行、颠倒善恶的众生聚集、合流到一起；错误理解解脱的法义，放纵自己的行为、言语、念想胡作非为的众生与错误理解解脱的法义，放纵自己的行为、言语、念想胡作非为的众生聚集、合流到一起。",-1),e("p",null,"弟子们，同样的道理，有正确见解的众生与有正确见解的众生聚集、合流到一起；有正确意愿的众生与有正确意愿的众生聚集、合流到一起；正语的众生与正语的众生聚集、合流到一起；由于善行将会获得善报的众生与由于善行将会获得善报的众生聚集、合流到一起；合法、正当谋生的众生与合法、正当谋生的众生聚集、合流到一起；向正确方向奋斗努力的众生与向正确方向奋斗努力的众生聚集、合流到一起；正念的众生与正念的众生聚集、合流到一起；用正确的修行方法让内心清净无染的众生与用正确的修行方法让内心清净无染的众生聚集、合流到一起；正确理解善行恶行、不颠倒善恶的众生与正确理解善行恶行、不颠倒善恶的众生聚集、合流到一起；正确理解解脱的法义，不放纵自己的行为、言语、念想胡作非为的众生与正确理解解脱的法义，不放纵自己的行为、言语、念想胡作非为的众生聚集、合流到一起。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(_,[["render",l]]);export{u as __pageData,f as default};
